const respuesta = $input.first().json;
const dinero = (valor) => '$' + Math.round(Number(valor) || 0).toLocaleString('es-CO');
const recordatorios = respuesta.recordatorios || [];
return recordatorios.filter((r) => r.telefono).map((r) => ({ json: { ...r, saldoTexto: dinero(r.saldoPendiente), fechaTexto: new Date(r.fechaVencimiento).toLocaleDateString('es-CO') } }));
